(()=>{const root=document.getElementById('I04-lab');if(!root)return;const zh=document.documentElement.lang.startsWith('zh'),tr=(a,b)=>zh?a:b,q=id=>root.querySelector('#I04-'+id);let s={angle:0,depth:50};const listeners=[];function render(){const t=s.angle*Math.PI/180,dx=16*Math.cos(t)+s.depth*Math.sin(t);s.projected_nm=Math.abs(dx);s.true_nm=Math.hypot(16,s.depth);s.overlap=s.projected_nm<24;q('angle').value=s.angle;q('depth').value=s.depth;let v='<rect width="800" height="330" fill="#faf9f5"/><path d="M70 260H730" stroke="#788b90"/>';for(let x=-60;x<=60;x+=20)v+=`<text x="${400+x*5}" y="285" text-anchor="middle">${x}</text>`;v+=`<circle cx="${400-dx*2.5}" cy="145" r="60" fill="#168477" fill-opacity=".65"/><circle cx="${400+dx*2.5}" cy="145" r="60" fill="#bd624b" fill-opacity=".65"/><text x="400" y="315" text-anchor="middle">${tr('投影横坐标 / nm','Projected horizontal position / nm')}</text><text x="400" y="30" text-anchor="middle">${tr('真实物体位置不随视角改变','Changing the view preserves the spatial arrangement')}</text>`;q('plot').innerHTML=v;q('result').textContent=tr('倾角','Tilt')+` ${s.angle}° · `+tr('真实中心距','True center distance')+` ${s.true_nm.toFixed(2)} nm · `+tr('投影中心距','Projected center distance')+` ${s.projected_nm.toFixed(2)} nm · `+(s.overlap?tr('投影轮廓重叠','Projected outlines overlap'):tr('投影轮廓分离','Projected outlines separate'));}function set(p){if(p.angle!==undefined)s.angle=Math.min(70,Math.max(-70,+p.angle));if(p.depth!==undefined)s.depth=Math.min(80,Math.max(0,+p.depth));render();return {...s}}function on(id,e,f){q(id).addEventListener(e,f);listeners.push([q(id),e,f])}on('angle','input',e=>set({angle:+e.target.value}));on('depth','input',e=>set({depth:+e.target.value}));const reset=()=>set({angle:0,depth:50});on('reset','click',reset);window.CourseLab={set,state:()=>({...s}),reset,destroy:()=>listeners.forEach(([n,e,f])=>n.removeEventListener(e,f))};render();})();
